<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
$customer=customer_required();
if(is_post()){
    try{
        verify_csrf();$action=scalar_string($_POST['action']??'profile');
        if($action==='profile'){
            $first=trim(scalar_string($_POST['first_name']??''));$last=trim(scalar_string($_POST['last_name']??''));$email=customer_normalize_email(scalar_string($_POST['email']??''));$marketing=isset($_POST['marketing_sms_enabled'])?1:0;
            if($first!==''&&(text_length($first)<2||text_length($first)>80))throw new RuntimeException('نام معتبر نیست.');
            if($last!==''&&(text_length($last)<2||text_length($last)>100))throw new RuntimeException('نام خانوادگی معتبر نیست.');
            if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('ایمیل معتبر نیست.');
            if($email!==''){$duplicate=db()->prepare('SELECT id FROM customers WHERE email=? AND id<>? LIMIT 1');$duplicate->execute([$email,$customer['id']]);if($duplicate->fetchColumn())throw new RuntimeException('این ایمیل در حساب دیگری ثبت شده است.');}
            $full=trim($first.' '.$last);$oldEmail=customer_normalize_email((string)($customer['email']??''));$emailVerified=hash_equals($oldEmail,$email)?($customer['email_verified_at']??null):null;db()->prepare('UPDATE customers SET first_name=?,last_name=?,full_name=?,email=?,email_verified_at=?,marketing_sms_enabled=? WHERE id=?')->execute([$first?:null,$last?:null,$full?:null,$email?:null,$emailVerified,$marketing,$customer['id']]);flash('success','مشخصات حساب با موفقیت ذخیره شد.');
        }elseif($action==='address'){
            $name=trim(scalar_string($_POST['recipient_name']??''));$phone=normalize_phone(scalar_string($_POST['recipient_phone']??''));$province=normalize_place_name(scalar_string($_POST['province']??''));$city=normalize_place_name(scalar_string($_POST['city']??''));$addressText=trim(scalar_string($_POST['address']??''));$postal=validate_iran_postal_code(scalar_string($_POST['postal_code']??''));
            if(text_length($name)<3||!preg_match('/^09\d{9}$/',$phone)||!in_array($province,iran_provinces(),true)||$city===''||text_length($addressText)<10||empty($postal['valid']))throw new RuntimeException('اطلاعات نشانی کامل نیست.');
            $pdo=db();$pdo->beginTransaction();$existing=$pdo->prepare('SELECT id FROM customer_addresses WHERE customer_id=? AND is_default=1 ORDER BY id DESC LIMIT 1 FOR UPDATE');$existing->execute([$customer['id']]);$addressId=(int)($existing->fetchColumn()?:0);$pdo->prepare('UPDATE customer_addresses SET is_default=0 WHERE customer_id=?')->execute([$customer['id']]);
            if($addressId>0)$pdo->prepare('UPDATE customer_addresses SET title=?,recipient_name=?,recipient_phone=?,province=?,city=?,address=?,postal_code=?,is_default=1 WHERE id=? AND customer_id=?')->execute(['نشانی اصلی',$name,$phone,$province,$city,$addressText,$postal['postal_code'],$addressId,$customer['id']]);
            else $pdo->prepare('INSERT INTO customer_addresses(customer_id,title,recipient_name,recipient_phone,province,city,address,postal_code,is_default) VALUES(?,?,?,?,?,?,?,?,1)')->execute([$customer['id'],'نشانی اصلی',$name,$phone,$province,$city,$addressText,$postal['postal_code']]);
            $pdo->commit();flash('success','نشانی اصلی با موفقیت ذخیره شد.');
        }
    }catch(Throwable $exception){if(db()->inTransaction())db()->rollBack();flash('error',public_exception_message($exception,'ذخیره اطلاعات حساب انجام نشد. دوباره تلاش کنید.'));}
    redirect(app_url('account.php'.($action==='address'?'#address':'#profile')));
}

$customer=customer_user(true);$customerId=(int)$customer['id'];$address=customer_default_address($customerId);
$ordersStmt=db()->prepare('SELECT * FROM orders WHERE customer_id=? ORDER BY id DESC LIMIT 100');$ordersStmt->execute([$customerId]);$orders=$ordersStmt->fetchAll();
$wishlist=customer_wishlist_products($customerId);
$summaryStmt=db()->prepare("SELECT COUNT(*) order_count,COALESCE(SUM(CASE WHEN o.order_status<>'cancelled' AND o.payment_status IN ('paid','partially_refunded','refunded') THEN GREATEST(o.total-COALESCE(rf.refunded_amount,0),0) ELSE 0 END),0) total_spent,SUM(o.order_status IN ('new','pending_payment','reviewing','sourcing','confirmed','preparing','ready_to_ship','handed_to_carrier','shipped')) active_orders,SUM(o.order_status IN ('delivered','installed')) delivered_orders FROM orders o LEFT JOIN (SELECT order_id,SUM(amount) refunded_amount FROM refund_transactions WHERE status='completed' GROUP BY order_id) rf ON rf.order_id=o.id WHERE o.customer_id=?");$summaryStmt->execute([$customerId]);$summary=$summaryStmt->fetch()?:[];
$ticketCount=0;if((string)setting('tickets_enabled','1')==='1'){$ticketStmt=db()->prepare("SELECT COUNT(*) FROM support_tickets WHERE customer_id=? AND status NOT IN ('closed')");$ticketStmt->execute([$customerId]);$ticketCount=(int)$ticketStmt->fetchColumn();}
$returnStmt=db()->prepare("SELECT COUNT(*) FROM return_requests WHERE customer_id=? AND status NOT IN ('rejected','closed','refunded')");$returnStmt->execute([$customerId]);$activeReturns=(int)$returnStmt->fetchColumn();
$profileFields=[trim((string)($customer['first_name']??''))!=='',trim((string)($customer['last_name']??''))!=='',trim((string)($customer['phone']??''))!=='',trim((string)($customer['email']??''))!=='',$address!==null];$profilePercent=(int)round(count(array_filter($profileFields))/count($profileFields)*100);
$displayName=trim((string)($customer['full_name']??''))?:trim((string)(($customer['first_name']??'').' '.($customer['last_name']??'')));if($displayName==='')$displayName='مشتری عزیز';
$picture=safe_external_url((string)($customer['google_picture_url']??''));
$pageKey='account';$pageTitle='حساب من | '.setting('store_name');$robots='noindex,nofollow';$headExtra='<link rel="stylesheet" href="'.e(asset('css/account-responsive.css')).'">';require BASE_PATH.'/app/views/header.php';
?>
<main class="customer-area"><div class="container account-dashboard">
<aside class="customer-sidebar"><div class="customer-profile-card"><?php if($picture):?><img src="<?=e($picture)?>" alt="تصویر حساب <?=e($displayName)?>" referrerpolicy="no-referrer"><?php else:?><span class="customer-avatar"><?=e(text_substr($displayName,0,1))?></span><?php endif?><div><strong><?=e($displayName)?></strong><small dir="ltr"><?=e($customer['phone']?:($customer['email']??''))?></small></div></div><nav class="customer-nav"><a class="active" href="#dashboard"><span>⌂</span> نمای کلی</a><a href="#orders"><span>□</span> سفارش‌های من</a><a href="#wishlist"><span>♡</span> علاقه‌مندی‌ها</a><a href="#profile"><span>○</span> مشخصات حساب</a><a href="#address"><span>⌖</span> نشانی اصلی</a><?php if((string)setting('tickets_enabled','1')==='1'):?><a href="<?=e(app_url('tickets.php'))?>"><span>◇</span> پشتیبانی و تیکت‌ها<?php if($ticketCount):?><b><?=fa_number($ticketCount)?></b><?php endif?></a><?php endif?></nav><div class="customer-sidebar__help"><strong>نیاز به راهنمایی دارید؟</strong><p>پشتیبانی فروشگاه پاسخ‌گوی شماست.</p><a href="<?=e(app_url('contact.php'))?>">تماس با ما</a></div><form method="post" action="<?=e(app_url('customer-logout.php'))?>"><?=csrf_field()?><button class="customer-logout">خروج از حساب</button></form></aside>
<div class="customer-content">
<?php foreach(flashes() as $flash):?><div class="flash <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endforeach?>
<section id="dashboard" class="customer-welcome"><div><span>حساب کاربری من</span><h1>سلام، <?=e($displayName)?></h1><p>از اینجا سفارش‌ها، علاقه‌مندی‌ها، نشانی و درخواست‌های پشتیبانی را مدیریت کنید.</p></div><a class="btn btn-light" href="<?=e(app_url('shop.php'))?>">ادامه خرید</a></section>
<section class="customer-stats"><article><span class="customer-stat__icon">□</span><div><small>همه سفارش‌ها</small><strong><?=fa_number((int)($summary['order_count']??0))?></strong></div></article><article><span class="customer-stat__icon">↻</span><div><small>در حال پردازش</small><strong><?=fa_number((int)($summary['active_orders']??0))?></strong></div></article><article><span class="customer-stat__icon">✓</span><div><small>تحویل‌شده</small><strong><?=fa_number((int)($summary['delivered_orders']??0))?></strong></div></article><article><span class="customer-stat__icon">♡</span><div><small>علاقه‌مندی‌ها</small><strong><?=fa_number(count($wishlist))?></strong></div></article></section>
<section class="customer-overview-grid"><div class="customer-panel profile-completion"><div class="customer-panel__head"><div><span class="eyebrow-dark">تکمیل حساب</span><h2>پروفایل شما <?=fa_number($profilePercent)?>٪ کامل است</h2></div><strong><?=fa_number($profilePercent)?>٪</strong></div><div class="completion-track"><span style="width:<?=$profilePercent?>%"></span></div><p><?= $profilePercent<100?'با تکمیل ایمیل و نشانی، ثبت سفارش بعدی سریع‌تر می‌شود.':'اطلاعات حساب شما کامل است.' ?></p><a href="<?=$profilePercent<80?'#profile':'#address'?>">بررسی اطلاعات ←</a></div><div class="customer-panel customer-quick-actions"><div class="customer-panel__head"><h2>دسترسی سریع</h2></div><div><a href="<?=e(app_url('track-order.php'))?>"><span>⌖</span><strong>رهگیری سفارش</strong><small>با شماره سفارش</small></a><?php if((string)setting('tickets_enabled','1')==='1'):?><a href="<?=e(app_url('tickets.php'))?>"><span>◇</span><strong>ثبت تیکت</strong><small><?=fa_number($ticketCount)?> تیکت باز</small></a><?php endif?><a href="#address"><span>⌂</span><strong>ویرایش نشانی</strong><small>برای ارسال سریع‌تر</small></a></div></div></section>
<?php if($activeReturns):?><div class="customer-notice"><span>↺</span><div><strong><?=fa_number($activeReturns)?> درخواست مرجوعی در حال بررسی دارید.</strong><p>وضعیت درخواست از جزئیات سفارش قابل مشاهده است.</p></div></div><?php endif?>
<section id="orders" class="customer-panel"><div class="customer-panel__head"><div><span class="eyebrow-dark">خریدهای شما</span><h2>سفارش‌های اخیر</h2></div><span class="muted customer-panel__summary">مجموع خرید پرداخت‌شده: <?=fa_number(format_price((int)($summary['total_spent']??0)))?> تومان</span></div><?php if($orders):?><div class="customer-orders"><?php foreach(array_slice($orders,0,8) as $order):?><a class="customer-order" href="<?=e(app_url('account-order.php?id='.(int)$order['id']))?>"><div class="customer-order__identity"><strong><?=e($order['order_number'])?></strong><small><?=e(jalali_date_format($order['created_at']))?></small></div><span class="order-status-pill status-<?=e($order['order_status'])?>"><?=e(order_status_label($order['order_status']))?></span><div class="customer-order__amount"><strong><?=fa_number(format_price($order['total']))?> تومان</strong><small><?=e(order_payment_status_label($order))?></small></div><b class="customer-order__arrow">←</b></a><?php endforeach?></div><?php else:?><div class="customer-empty"><span>□</span><h3>هنوز سفارشی ثبت نکرده‌اید</h3><p>محصولات فروشگاه را ببینید و اولین خریدتان را شروع کنید.</p><a class="btn btn-primary" href="<?=e(app_url('shop.php'))?>">مشاهده محصولات</a></div><?php endif?></section>
<section id="wishlist" class="customer-panel"><div class="customer-panel__head"><div><span class="eyebrow-dark">ذخیره‌شده‌ها</span><h2>علاقه‌مندی‌های من</h2></div><span class="muted"><?=fa_number(count($wishlist))?> کالا</span></div><div class="wishlist-grid"><?php foreach(array_slice($wishlist,0,8) as $item):?><article class="wishlist-card"><img src="<?=e(public_image((string)$item['image_path']))?>" alt="<?=e($item['short_title']?:$item['title'])?>"><div><a href="<?=e(product_url($item))?>"><strong><?=e($item['short_title']?:$item['title'])?></strong></a><p><?=fa_number(format_price($item['price']))?> تومان</p><button type="button" class="btn btn-secondary" data-wishlist="<?=$item['id']?>">حذف</button></div></article><?php endforeach?><?php if(!$wishlist):?><div class="customer-empty customer-empty--compact"><span>♡</span><p>هنوز کالایی به علاقه‌مندی‌ها اضافه نکرده‌اید.</p></div><?php endif?></div></section>
<section id="profile" class="customer-panel"><div class="customer-panel__head"><div><span class="eyebrow-dark">اطلاعات شخصی</span><h2>مشخصات حساب</h2></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="profile"><div class="form-grid"><div class="field"><label>نام</label><input name="first_name" maxlength="80" value="<?=e($customer['first_name']??'')?>"></div><div class="field"><label>نام خانوادگی</label><input name="last_name" maxlength="100" value="<?=e($customer['last_name']??'')?>"></div><div class="field"><label>شماره همراه</label><input value="<?=e($customer['phone']??'')?>" disabled><small>شماره همراه برای امنیت حساب از این بخش قابل تغییر نیست.</small></div><div class="field"><label>ایمیل</label><input type="email" name="email" maxlength="190" value="<?=e($customer['email']??'')?>"><small><?=!empty($customer['email_verified_at'])?'ایمیل تأیید شده است.':'ایمیل هنوز تأیید نشده است.'?></small></div><div class="field full checkboxes"><label><input type="checkbox" name="marketing_sms_enabled" <?=!empty($customer['marketing_sms_enabled'])?'checked':''?>> دریافت پیامک جشنواره‌ها و پیشنهادهای فروشگاه</label></div></div><button class="btn btn-primary">ذخیره مشخصات</button><?php if(customer_google_enabled()):?><?php if(empty($customer['google_sub'])):?><a class="btn btn-secondary" href="<?=e(app_url('google-auth.php?from=link'))?>">اتصال امن حساب Google</a><?php else:?><span class="muted">حساب Google متصل است.</span><?php endif?><?php endif?></form></section>
<section id="address" class="customer-panel"><div class="customer-panel__head"><div><span class="eyebrow-dark">تحویل سفارش</span><h2>نشانی اصلی</h2></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="address"><div class="form-grid"><div class="field"><label>نام گیرنده</label><input name="recipient_name" maxlength="160" value="<?=e($address['recipient_name']??($customer['full_name']??''))?>" required></div><div class="field"><label>موبایل گیرنده</label><input name="recipient_phone" inputmode="numeric" maxlength="11" value="<?=e($address['recipient_phone']??($customer['phone']??''))?>" required></div><div class="field"><label>استان</label><select name="province" required><option value="">انتخاب کنید</option><?php foreach(iran_provinces() as $province):?><option value="<?=e($province)?>" <?=($address['province']??'')===$province?'selected':''?>><?=e($province)?></option><?php endforeach?></select></div><div class="field"><label>شهر</label><input name="city" maxlength="100" value="<?=e($address['city']??'')?>" required></div><div class="field full"><label>نشانی کامل</label><textarea name="address" maxlength="2000" rows="4" required><?=e($address['address']??'')?></textarea></div><div class="field"><label>کدپستی</label><input name="postal_code" inputmode="numeric" maxlength="10" value="<?=e($address['postal_code']??'')?>" required></div></div><button class="btn btn-primary">ذخیره نشانی</button></form></section>
